 {                 
     LOCK(m_mutex);
     auto iters = Find(tx->GetHash());
-    if (!iters) {
+    if (!iters || iters->by_txid->second.tx->GetWitnessHash() != tx->GetWitnessHash()) {
         return std::nullopt;
     }
     const size_t num_broadcasted{iters->by_priority->first.num_broadcasted};
     m_by_priority.erase(iters->by_priority);
     m_by_txid.erase(iters->by_txid);
     return num_broadcasted;
```
</details>

With this, if a malleated and valid transaction makes it to our mempool, then we would keep broadcasting the original one, up to 5 times, and then it will be removed by `PeerManagerImpl::ReattemptPrivateBroadcast()`.

Which one?

