comments.body:
I've been testing sending multiple `walletcreatefundedpsbt`s in quick successions. Since we are single threaded, the first connection is opened and we send the tx. The second connection is opened and we send the tx. Sometimes before we even connect to the second peer to send the second tx we receive the first tx, so we stop connections for the first tx. However, we still go through the motions of sending the second tx three more times.

I tried the same with the below patch, and before we push the tx in the second connection we will stop as well.

```diff
diff --git a/src/net_processing.cpp b/src/net_processing.cpp
index 94b398daf6..d76ebd3b6c 100644
--- a/src/net_processing.cpp
+++ b/src/net_processing.cpp
@@ -3531,6 +3531,25 @@ void PeerManagerImpl::PushPrivateBroadcastTx(CNode& node)
     }
     const CTransactionRef& tx{*opt_tx};
 
+    const auto mempool_acceptable{WITH_LOCK(cs_main, return m_chainman.ProcessTransaction(tx, /*test_accept=*/true))};
+    if (mempool_acceptable.m_result_type != MempoolAcceptResult::ResultType::VALID) {
+        LogPrintLevel(BCLog::PRIVATE_BROADCAST,
+            BCLog::Level::Info,
+            "Giving up broadcast attempts for txid=%s wtxid=%s: %s",
+            tx->GetHash().ToString(),
+            tx->GetWitnessHash().ToString(),
+            mempool_acceptable.m_state.ToString());
+        if (const auto num_broadcasted{m_tx_for_private_broadcast.Remove(tx)}) {
+            if (NUM_PRIVATE_BROADCAST_PER_TX > num_broadcasted.value()) {
+                // Not all of the initial NUM_PRIVATE_BROADCAST_PER_TX connections were needed.
+                // Tell CConnman it does not need to start the remaining ones.
+                m_connman.m_private_broadcast.NumToOpenSub(NUM_PRIVATE_BROADCAST_PER_TX - num_broadcasted.value());
+            }
+        }
+        node.fDisconnect = true;
+        return;
+    }
+
     LogPrintLevel(BCLog::PRIVATE_BROADCAST,
                   BCLog::Level::Info,
                   "P2P handshake completed, sending txid=%s%s, peer=%d%s",

```

