bool IsPrivateBroadcastAllowed(std::string_view type) noexcept
{
    return type == NetMsgType::VERSION
        || type == NetMsgType::VERACK
        || type == NetMsgType::INV
        || type == NetMsgType::TX
        || type == NetMsgType::PING;
